/**
 * Canonical automation model shapes — single source of truth for
 * every antman/mobius endpoint that returns an automation or any of
 * its pieces:
 *
 *   - `Aspect.automations` (catalog view from `GET /v1/apps/definition`)
 *     populates `Automation` with `id`, `name`, and shallow
 *     `workflowCurrent` / `workflowDraft` carrying trigger metadata.
 *   - `GET /api/v1/workflows/{id}` (full-state view from mobius)
 *     populates `Workflow` + `WorkflowTrigger` + `WorkflowTask` +
 *     `WorkflowOutput` with deeper runtime detail.
 *
 * Different endpoints populate different fields on the same types.
 * Every field that isn't required by both callers is optional so the
 * same shape covers both views without forcing synthetic "Ref" or
 * "View" variants. Each field documents which endpoints drive it.
 */
import type { AutomationOwnerType, Owner } from "../../../../fs/entity.js";
import type { Filter } from "../../../../src/entities/shared/filters/types.js";
import type { WorkflowFieldType } from "../../../../src/entities/shared/types/field-types.js";
export interface TriggerParameter {
    readonly id: string;
    readonly name: string;
    /**
     * Field type of the parameter. Surfaced by antman's catalog endpoint
     * directly from mobius's `ServiceTaskParam.fieldType` and always
     * populated for onDemand triggers (verified live against
     * `/v1/apps/definition`). The renderer translates this into the
     * SDK-side `AppAutomationParam.type`.
     */
    readonly fieldType: WorkflowFieldType;
    readonly required?: boolean;
}
export interface WorkflowTrigger {
    /** Discriminator on the catalog view (`WorkflowOnDemandTrigger`, `WorkflowRecordCreateTrigger`, …). */
    readonly __typename?: string;
    readonly id: string;
    /** Populated by the catalog view — pre-extracted onDemand inputs. */
    readonly parameters?: readonly TriggerParameter[];
    /** Populated by the full-state view — raw properties keyed by mobius's `type` discriminator. */
    readonly properties?: {
        readonly type: string;
        readonly [key: string]: unknown;
    };
}
export interface WorkflowOutput {
    /** Catalog gives a stable id; full-state omits it on in-line outputs. */
    readonly id?: string;
    readonly referenceId?: string;
    readonly name: string;
    /** Full-state view carries the runtime value reference; catalog does not. */
    readonly value?: Record<string, unknown>;
}
/**
 * Inner task body — mirrors mobius's `WorkflowTask` Java record.
 * Used in two places:
 *
 *   1. The catalog view (antman's `Aspect.automations.workflow*.tasks`)
 *      surfaces these directly with minimal fields ({id, __typename})
 *      so the agent can preview a workflow's task graph.
 *   2. The full-state view nests these under a `WorkflowTaskView`
 *      wrapper that adds the server-derived `refKey` and grouped
 *      `children` operator structure.
 *
 * The `[key: string]: unknown` escape carries the metadata fields the
 * deserializer doesn't read (workflowId, organizationId, createdAt,
 * createdBy, …).
 */
export interface WorkflowTask {
    readonly id: string;
    readonly type?: string;
    readonly name?: string;
    readonly properties?: {
        readonly type: string;
        readonly [key: string]: unknown;
    };
    readonly parentWorkflowTaskId?: string | null;
    readonly child?: boolean;
    readonly [key: string]: unknown;
}
/**
 * A switch case / forEach body — the grouped child structure mobius
 * returns under each operator task on the full-state view.
 *
 *   - `label` is the case label (empty string for the SWITCH default,
 *      `null` for forEach since it has only one branch).
 *   - `filter` is the case predicate (only set on SWITCH children).
 *   - `tasks` is the recursive list of `WorkflowTaskView` entries that
 *      run inside this branch.
 */
export interface WorkflowOperatorChildView {
    readonly label: string | null;
    readonly filter?: Filter;
    readonly tasks: readonly WorkflowTaskView[];
}
/**
 * Full-state task entry — the wrapped tree shape mobius returns from
 * `GET /api/v1/workflows/{id}` since PR #8.
 *
 * Each entry pairs a server-derived `refKey` (the slug downstream
 * deserializers use to identify a task) with the inner `WorkflowTask`
 * body. Operator tasks (SWITCH, FOR_EACH) also carry a `children`
 * array — one entry per case — so callers don't have to reassemble
 * branches from a flat list.
 */
export interface WorkflowTaskView {
    readonly refKey: string;
    readonly task: WorkflowTask;
    readonly children?: readonly WorkflowOperatorChildView[];
}
/**
 * A version of an automation — what antman aliases as
 * `workflowCurrent` or `workflowDraft` on an `Automation`, or what
 * the full-state response returns as its `workflow` field. Covers
 * all three through optional fields; each field documents which
 * endpoint populates it.
 *
 * Note on outputs: antman's catalog view returns `outputs` directly
 * on the workflow (per the GraphQL `workflowFragment`). Mobius's
 * full-state responses return `outputProperties` at the response root.
 * Older/sparse full-state payloads may omit that field, so the pull
 * path can fall back to catalog outputs when available.
 */
export interface Workflow {
    readonly id?: string;
    readonly automationId?: string;
    readonly workflowId?: string;
    readonly name?: string;
    readonly status?: string;
    readonly ownerId?: string;
    readonly ownerType?: AutomationOwnerType;
    readonly owner?: Owner<AutomationOwnerType>;
    readonly triggers?: readonly WorkflowTrigger[];
    readonly outputs?: readonly WorkflowOutput[];
    readonly tasks?: readonly WorkflowTask[];
    readonly workflow?: {
        readonly version?: Number;
        readonly status?: string;
        readonly name: string;
    };
}
/**
 * An automation as it appears inside `Aspect.automations` on the
 * catalog view.
 *
 * `id` is the long-lived automation container id — the one
 * `runAutomation` task refs use to invoke this automation.
 *
 * `workflowCurrent` and `workflowDraft` are antman-aliased fields
 * (`current` / `draft` on the underlying GraphQL `Automation`).
 * Each carries its own `Workflow.id` (a versioned workflow id) —
 * that's what `automation.fromJSON(workflowId)` needs. Pull
 * flows prefer `workflowDraft.id` when present (the in-progress
 * edit) and fall back to `workflowCurrent.id` (the deployed live
 * version).
 */
export interface Automation {
    readonly id: string;
    readonly name: string;
    /** Server-assigned stable handle (e.g. `AUTO_ck3ifggq`); preferred over a name-derived handle. */
    readonly clientHandle?: string;
    /**
     * Immutable creation timestamp (ISO-8601). Primary ordering key for
     * deterministic handle minting (`src/handles`); optional, falls back to
     * `id` ordering when absent.
     */
    readonly createdAt?: string;
    readonly workflowCurrent?: Workflow;
    readonly workflowDraft?: Workflow;
}
